/* ---------- Comments ---------- */
/* a thread on one spot of a design: the first comment, then its replies indented on a thin line. Each comment is an avatar,
   a name, a time and the text; its Agree button shows on hover or keyboard focus (always, on a touch screen). The card's
   content is 16px from every edge in every style, and it keeps no room for replies still to come: it grows as they arrive
   (grow()) and stays centred in its stage (owner, 17 and 18 Nov). Hovers are a quiet fill that shows in light mode too */
.cmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
/* the head sits on the comments' columns: the pin centred in the avatars' 24px column, the title where their words start,
   and Resolve's glyph on the right edge the Send button ends on, its hover box reaching out round it */
.cmx-h{display:flex;align-items:center;gap:var(--dm-s-3);min-height:20px;padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:20px}
.cmx-h b{font-weight:500}
.cmx-st{flex:1;min-width:0;display:flex}
.cmx-pin{width:20px;height:20px;margin:0 2px;border-radius:50% 50% 50% var(--dm-r-xs);background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;font-size:11px;font-weight:500;flex:none;transition:background var(--dm-t)}
.cmx.done .cmx-pin{background:var(--dm-ok);color:var(--dm-surface)}
.cmx-res{width:28px;height:28px;margin:-4px -3px -4px 0;color:var(--dm-muted)}
.cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 50%,var(--dm-surface));display:flex;flex-direction:column;gap:var(--dm-s-4);flex:1}
/* dark: the rail is close to the surface already, so the line keeps more of it to stay visible */
:root[data-theme="dark"] .cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 80%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .cmx-th{--dm-cmx-ln:color-mix(in srgb,var(--dm-rail) 80%,var(--dm-surface))}}
/* a reply's avatar starts where the words of the comment it answers start (12px + 24px in), so the thread keeps one column */
.cmx-rp{--dm-cmx-x:calc(-1 * var(--dm-s-6) - .75px);display:flex;flex-direction:column;gap:var(--dm-s-4);margin-left:var(--dm-s-3);padding-left:var(--dm-s-6);position:relative}
/* one unbroken line (owner, 21 Nov: "these lines are not connected"): it starts just below the first comment's avatar,
   centred under it, and runs straight down to the last reply's branch, where it ends. Every piece of it is drawn the same
   way, a 1.5px left border at the same x, and each piece overlaps the next, so they meet with no seam */
:is(.cmx-th,.cmx-th>.dm-grow)>.cmx-c:first-child{position:relative}
:is(.cmx-th,.cmx-th>.dm-grow)>.cmx-c:first-child:has(+ .cmx-rp)::before{content:'';position:absolute;width:0;border-left:1.5px solid var(--dm-cmx-ln);pointer-events:none;left:calc(var(--dm-s-3) - .75px);top:calc(24px + var(--dm-s-1));bottom:calc(-1 * var(--dm-s-4))}
/* each reply: a branch leaves the line and turns into its avatar's centre (rounded in Soft and Clean, square in Blueprint);
   under every reply but the last the line carries straight on past the branch, and as a reply arrives the line draws itself
   down to it */
.cmx-rp>.cmx-c{position:relative}
.cmx-rp>.cmx-c .av{position:relative;z-index:1}
.cmx-rp>.cmx-c::before{content:'';position:absolute;left:var(--dm-cmx-x);top:calc(-1 * var(--dm-s-4));width:calc(var(--dm-s-6) + 1.75px);height:calc(var(--dm-s-4) + 12.75px);box-sizing:border-box;border-left:1.5px solid var(--dm-cmx-ln);border-bottom:1.5px solid var(--dm-cmx-ln);border-bottom-left-radius:10px;corner-shape:round;pointer-events:none}
.cmx-rp>.cmx-c:not(:last-child)::after{content:'';position:absolute;left:var(--dm-cmx-x);top:0;bottom:calc(-1 * var(--dm-s-4));width:0;border-left:1.5px solid var(--dm-cmx-ln);pointer-events:none;transform-origin:top;animation:cmxrl var(--dm-t) var(--dm-ease) both}
@keyframes cmxrl{from{transform:scaleY(0)}}
:root:not([data-style="soft"],[data-style="clean"]) .cmx-rp>.cmx-c:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{border-bottom-left-radius:0}
.cmx-c{display:flex;gap:var(--dm-s-3);min-width:0}
.cmx-c .av{width:24px;height:24px;font-size:10px}
.cmx-c .b{flex:1;display:flex;flex-direction:column;min-width:0}
.cmx-c .n{display:flex;align-items:center;gap:var(--dm-s-2);height:24px;font-size:13px}
.cmx-c .n b{font-weight:500;white-space:nowrap}
.cmx-c .n .t{font-size:12px;color:var(--dm-muted)}
.cmx-c .tx{font-size:13.5px;line-height:1.5;color:var(--dm-fg);overflow-wrap:anywhere}
/* an @mention: the accent's text on its tint, the tint reaching out round the word so the word stays on the text's column */
.cmx-c .m{color:var(--dm-accent-fg);background:var(--dm-sel);border-radius:var(--dm-r-xs);padding:0 2px;margin:0 -2px}
.cmx-c.ag .tx .w{animation:cmw .4s var(--dm-ease) both}
@keyframes cmw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
/* the agent's buttons wrap before they reach the column's right edge, so on a phone they never end a few pixels short of the
   edge Send and Resolve end on */
.cmx-c .act{display:flex;flex-wrap:wrap;gap:var(--dm-s-2);margin-top:var(--dm-s-2);max-width:calc(100% - var(--dm-s-6))}
/* the quiet Agree button beside the time, its glyph on the same right edge as Resolve's */
.cmx-tools{margin-left:auto;margin-right:-2px;display:flex;gap:var(--dm-s-1);transition:opacity var(--dm-t-fast)}
.cmx-tools .ib{width:26px;height:26px;color:var(--dm-muted)}
.cmx-tools .ib[aria-pressed="true"]{color:var(--dm-accent-fg)}
@media (hover:hover) and (pointer:fine){.cmx-tools{opacity:0}}
.cmx-c .n:focus-within .cmx-tools{opacity:1}
@media (hover:hover) and (pointer:fine){.cmx-c:hover .cmx-tools{opacity:1}}
/* how many agreed: a small chip under the text. Hovered it takes a quiet fill; once you have agreed it takes the accent's
   tint with the accent's text, as a reaction of yours does (owner, 20 Nov: hover and selected are a quiet, deeper fill) */
.cmx-rs{display:flex;margin-top:var(--dm-s-2)}
.cmx-rs:has(.cmx-rc[hidden]){display:none}
.cmx-rc{display:inline-flex;align-items:center;gap:var(--dm-s-1);height:22px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-pill);font-size:12px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);transition:background-color var(--dm-t-fast),box-shadow var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.cmx-rc:hover{background:color-mix(in srgb,var(--dm-fg) 5%,var(--dm-surface))}}
.cmx-rc[aria-pressed="true"]{color:var(--dm-accent-fg);background:var(--dm-accent-bg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark) 25%,transparent)}
@media (hover:hover) and (pointer:fine){.cmx-rc[aria-pressed="true"]:hover{background:linear-gradient(color-mix(in srgb,var(--dm-fg) 4%,transparent),color-mix(in srgb,var(--dm-fg) 4%,transparent)),var(--dm-accent-bg)}}
/* the reply field: a dimmed edge at rest, one step stronger while it has the focus, and no ring. A half-strength hairline
   sets it off from the thread, as one sets the head off (owner, 21 Nov) */
.cmx-in{position:relative;display:grid;grid-template-rows:minmax(0,1fr);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);transition:grid-template-rows var(--dm-t) var(--dm-ease),margin var(--dm-t) var(--dm-ease),padding var(--dm-t) var(--dm-ease),border-width var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),visibility 0s}
.cmx-box{display:flex;align-items:center;gap:6px;height:var(--dm-field-h);padding:0 5px 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.cmx-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.cmx-box:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.cmx-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13.5px;color:var(--dm-fg)}
.cmx-box input::placeholder{color:var(--dm-muted)}
.cmx-go{width:30px;height:30px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.cmx-go:hover{background:var(--dm-accent-2)}}
.cmx-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}
@media (hover:hover) and (pointer:fine){.cmx-go[disabled]:hover{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring);transform:none}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink Send alone presses */
.cmx :is(.ib,.pill,.cmx-go,.cmx-rc):active,:root[data-style="clean"] .cmx .ib:active,:root [data-style="clean"] .cmx .ib:active,:root [data-style="clean"].cmx .ib:active{transform:none}
/* the mention list opens upward from the field, over the thread */
.cmx-men{bottom:46px;left:0;min-width:210px;--dm-origin:bottom left}
/* resolved: the thread stays as it is, in full colour (owner, 20 Nov: nothing fades to say it is past), the pin turns green,
   a green Resolved chip says so, and the reply field folds away while the card eases to its new height; Reopen brings it back */
.cmx.done .cmx-in{grid-template-rows:minmax(0,0fr);margin-top:calc(-1 * var(--dm-s-4));padding-top:0;border-top-width:0;opacity:0;overflow:hidden;visibility:hidden;transition:grid-template-rows var(--dm-t) var(--dm-ease),margin var(--dm-t) var(--dm-ease),padding var(--dm-t) var(--dm-ease),border-width var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease),visibility 0s var(--dm-t)}
@media (prefers-reduced-motion:reduce){.cmx-in{transition:none!important}.cmx-rp>.cmx-c::after{animation:none}}
.cmx-st .tag{margin-left:calc(-1 * var(--dm-s-1))}
/* the agent's change applied: a neutral line with the green tick (owner, 18 Nov: a finished state has no green words or fill) */
.cmx-rv{font-size:12.5px;line-height:28px;color:var(--dm-fg2);display:flex;align-items:center;gap:6px}
.cmx-rv svg{color:var(--dm-ok-mark)}
:root:not([data-style="soft"],[data-style="clean"]) .cmx-c .m:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 -1px 0 var(--dm-accent-mark)}
/* Clean: the head is a strip, its controls on the content's 16px column, and the reply field sits in a foot strip that folds
   away with it once the thread is resolved (owner, 21 Nov). Send is the field's own Send (see the Clean section): 5px from
   the field's edges, its corners the field's less those 5px. The agent's words fade in without a blur */
:root[data-style="clean"] .cmx-h,:root [data-style="clean"] .cmx-h,:root [data-style="clean"].cmx-h{margin:calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4)) 0;padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .cmx-res,:root [data-style="clean"] .cmx-res,:root [data-style="clean"].cmx-res{margin:0}
:root[data-style="clean"] .cmx-in,:root [data-style="clean"] .cmx-in,:root [data-style="clean"].cmx-in{margin:0 calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4));padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .cmx.done .cmx-in,:root [data-style="clean"] .cmx.done .cmx-in,:root [data-style="clean"].cmx.done .cmx-in{margin:calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4)) 0;padding-block:0;border-top-width:0}
:root[data-style="clean"] .cmx-men,:root [data-style="clean"] .cmx-men,:root [data-style="clean"].cmx-men{bottom:54px;left:var(--dm-s-4)}
:root[data-style="clean"] .cmx-go,:root [data-style="clean"] .cmx-go,:root [data-style="clean"].cmx-go{border-radius:calc(var(--dm-r-field) - 5px)}
:root[data-style="clean"] .cmx-c.ag .tx .w,:root [data-style="clean"] .cmx-c.ag .tx .w,:root [data-style="clean"].cmx-c.ag .tx .w{animation:cmwc var(--dm-t-slow) var(--dm-ease) both}
@keyframes cmwc{from{opacity:0}to{opacity:1}}

DM.def('comments', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{check}', I('check','xs')).replace('{up}', I('up','xs'));
  const root = $('.cmx', r), th = $('.cmx-th', r), inp = $('.cmx-box input', r), go = $('.cmx-go', r), men = $('.cmx-men', r), st = $('.cmx-st', r), rs = $('.cmx-res', r);
  const P = { MK:['Maya Kim','var(--dm-av-l)'], JO:['Jon Ortiz','var(--dm-av-m)'], DA:['Design agent','var(--dm-av-b)'] };
  const esc = t => t.replace(/[&<>"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' })[ch]);
  const fmt = t => esc(t).replace(/@(agent|maya|jon)\b/gi, m => `<span class="m">${m}</span>`);
  // the first comment starts the thread; every later one is a reply, indented on a thin line under it
  let rp = null;
  // the head says nothing the thread below already shows (owner, 19 Nov: no count of the replies); once the thread is
  // resolved, a green Resolved chip says so
  const count = () => { const d = root.classList.contains('done'), had = !!st.firstChild; if (d === had) return; st.innerHTML = d ? '<span class="tag ok">Resolved</span>' : ''; if (d) enter(st.firstChild); };
  function add(who, t, when, ag, agreed = 0){
    const el = html(`<div class="cmx-c${ag ? ' ag' : ''}">${AV(who, P[who][1])}<div class="b"><div class="n"><b>${P[who][0]}</b><span class="t">${when}</span><div class="cmx-tools"><button class="ib cmx-rx" aria-label="Agree" aria-pressed="false" data-tip="Agree">${I('up-thumb','xs')}</button></div></div><div class="tx">${ag ? '' : fmt(t)}</div><div class="cmx-rs"><button class="cmx-rc" aria-pressed="false" hidden>${I('up-thumb','xs')}<span class="num"></span></button></div></div></div>`);
    el._agree = { n:agreed, mine:false }; agree(el);
    $('.cmx-rx', el).onclick = () => agree(el, true); $('.cmx-rc', el).onclick = () => agree(el, true);
    // (once the thread grows with what it holds, its comments live in grow()'s wrapper)
    const box = $(':scope>.dm-grow', th) || th;
    if (!box.firstElementChild) box.appendChild(el);
    else { if (!rp){ rp = html('<div class="cmx-rp" role="group" aria-label="Replies"></div>'); box.appendChild(rp); } rp.appendChild(el); }
    enter(el); count(); return el;
  }
  // Agree: the button by the time and the chip under the text both toggle yours, and the chip counts everyone's
  function agree(el, flip){
    const a = el._agree; if (flip) a.mine = !a.mine;
    const n = a.n + (a.mine ? 1 : 0), b = $('.cmx-rx', el), chip = $('.cmx-rc', el), had = document.activeElement === chip;
    b.setAttribute('aria-pressed', a.mine); chip.setAttribute('aria-pressed', a.mine);
    chip.setAttribute('aria-label', 'Agree, ' + n + (n === 1 ? ' person' : ' people') + (a.mine ? ', including you' : ''));
    $('.num', chip).textContent = n; chip.hidden = !n;
    if (had && !n) b.focus({ preventScroll:true });
  }
  add('MK', 'The secondary button feels too faint next to the CTA.', '2h', false, 1);
  add('JO', 'Agree. Can we keep it outlined though?', '1h');
  async function agent(q){
    const el = add('DA', '', 'now', true), tx = $('.tx', el); tx.innerHTML = '<span class="think on" style="color:var(--dm-accent-mark,var(--dm-accent))"><i></i><i></i><i></i><i></i></span>'; await c.wait(900); tx.innerHTML = '';
    const a = /outline|border/i.test(q + ' outlined') ? 'Kept it outlined and raised the text to #5B6472, which passes AA at 5.9 : 1. Want me to apply it to the other 2 frames?' : 'On it. I will post the change here when it is ready.';
    for (const w of a.split(' ')){ tx.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(40); }
    const act = html(`<div class="act"><button class="pill primary sm">Apply to all</button><button class="pill line sm">Just this one</button></div>`); $('.b', el).appendChild(act); enter(act);
    $$('button', act).forEach((b, i) => b.onclick = () => { act.innerHTML = `<span class="cmx-rv">${I('ok','xs')}${i ? 'Applied to frame 2' : 'Applied to 3 frames'}</span>`; enter(act.firstChild); });
  }
  function send(){ const v = inp.value.trim(); if (!v) return; add('MK', v, 'now'); inp.value = ''; go.disabled = true; shut(); if (/@agent/i.test(v)) c.run(() => agent(v)); }
  const opts = [['DA','agent','Design agent'],['MK','maya','Maya Kim'],['JO','jon','Jon Ortiz']];
  // the reply box drives the list of people to mention: it is a combobox, and the highlighted row is its active option
  men.id = 'cmx-m-' + Math.random().toString(36).slice(2, 7); men.setAttribute('aria-label', 'Mention');
  inp.setAttribute('role', 'combobox'); inp.setAttribute('aria-autocomplete', 'list'); inp.setAttribute('aria-expanded', 'false'); inp.setAttribute('aria-controls', men.id);
  let hl = 0;
  const mens = () => $$('.mi', men);
  const light = k => { const all = mens(); if (!all.length){ inp.removeAttribute('aria-activedescendant'); return; } hl = (k + all.length) % all.length; all.forEach((b, j) => { b.classList.toggle('hl', j === hl); b.setAttribute('aria-selected', j === hl); }); inp.setAttribute('aria-activedescendant', all[hl].id); };
  const shut = () => { men.classList.remove('open'); inp.setAttribute('aria-expanded', 'false'); inp.removeAttribute('aria-activedescendant'); };
  inp.oninput = () => { go.disabled = !inp.value.trim(); const m = inp.value.match(/@(\w*)$/);
    if (m){ const list = opts.filter(o => o[1].startsWith(m[1].toLowerCase())); men.innerHTML = list.map(o => `<button class="mi" role="option" tabindex="-1" id="${men.id}-${o[1]}" data-h="${o[1]}">${AV(o[0], P[o[0]][1]).replace('class="av" style="', 'class="av" style="width:20px;height:20px;font-size:9px;')}<span>${o[2]}<span class="d">@${o[1]}</span></span></button>`).join(''); men.classList.toggle('open', list.length > 0); inp.setAttribute('aria-expanded', list.length > 0); light(0);
      $$('.mi', men).forEach(b => b.onmousedown = e => { e.preventDefault(); inp.value = inp.value.replace(/@\w*$/, '@' + b.dataset.h + ' '); shut(); go.disabled = false; inp.focus({ preventScroll:true }); }); }
    else shut(); };
  // with the mention list open, the up and down arrows move through it and wrap, Enter picks, and Escape closes it
  inp.onkeydown = e => {
    const open = men.classList.contains('open') && mens().length;
    if (open && (e.key === 'ArrowDown' || e.key === 'ArrowUp')){ e.preventDefault(); light(hl + (e.key === 'ArrowDown' ? 1 : -1)); return; }
    if (e.key === 'Enter'){ const f = mens()[hl]; if (open && f){ f.onmousedown(e); } else send(); }
    if (e.key === 'Escape') shut(); };
  go.onclick = send;
  // Resolve turns the pin green, says Resolved and folds the reply field away; the thread keeps its colours. Pressed again
  // it reopens
  rs.onclick = () => { const d = root.classList.toggle('done'); hideTip(); rs.innerHTML = I(d ? 'undo' : 'check', 'xs'); rs.setAttribute('aria-pressed', d); rs.dataset.tip = d ? 'Reopen thread' : 'Resolve thread'; count(); };
  // no room is kept for what is to come: the thread eases taller as replies arrive and the agent's words stream in (grow()),
  // and the reply field under it glides down with it, never cut; the card follows, centred in its stage. grow() starts once the
  // card's entrance (which scales it) has ended, so it measures the thread at its real size
  Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && th.isConnected) c.offs.push(grow(th)); });
  // the preview asks the agent in the thread on its own; clicking, focusing or typing in it takes over, and what it had
  // typed goes. The agent replying is an agent at work (DM.PLAYS): it carries on under the pointer, while the person's own
  // typing and sending wait for a mouse resting on the thread to leave, so nothing moves under it
  const free = async () => { while (r.matches(':hover')) await c.step(200); };
  c.auto(1000, () => c.run(async () => { await free(); await c.type(inp, '@agent can you keep it outlined but darker?', { ms:28, each:() => inp.oninput(), keep:true }); shut(); await c.step(300); await free(); send(); }));
});
